    func installWebappFromUrl(deviceId: String, url: String, expected: ArtifactDigest?, provenance: String?) async throws  -> WebappInfo
    
    func listWebappConfig(deviceId: String, id: String) async throws  -> [ConfigEntry]
    
    func listWebappDoc(deviceId: String, id: String) async throws  -> [DocEntry]
    
    func listWebapps(deviceId: String) async throws  -> [WebappInfo]
    
    func logInbox()  -> LogInbox
    
    func otaRunProgress(deviceId: String, nowMs: UInt64)  -> OtaRunProgress?
    
    func resumed() async 
    
    func setCapabilityFlags(flags: CapabilityFlags) async 
    
    func setDeviceAutoResume(deviceId: String, enabled: Bool) async 
    
