    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CompanionError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Cancelled(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .Runtime(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .NotConnected(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .Device(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .ResourceNotAvailable(
